<div class="content-wrapper"><section class="content-header"><h1>Surat Pengawasan KSOP</h1></section><section class="content"><?php if($error): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?><div class="box box-primary"><div class="box-body"><form method="post" enctype="multipart/form-data"><?php $this->load->view('pipeline/billing_token'); ?><div class="row"><div class="col-sm-6 form-group"><label>Area</label><select name="SpbbID" class="form-control" required><?php foreach($branches as $b): ?><option value="<?= (int)$b['SpbbID'] ?>"><?= html_escape($b['SpbbName']) ?></option><?php endforeach; ?></select></div><div class="col-sm-6 form-group"><label>Surat Bunker (opsional)</label><select name="BunkerID" class="form-control"><option value="">Tanpa tautan</option><?php foreach($requests as $r): ?><option value="<?= (int)$r['BunkerID'] ?>"><?= html_escape($r['RequestNo'].' / Area '.$r['SpbbID']) ?></option><?php endforeach; ?></select></div><div class="col-sm-6 form-group"><label>Nomor Surat KSOP</label><input name="ReferenceNo" maxlength="100" class="form-control" required></div><div class="col-sm-6 form-group"><label>Tanggal Surat</label><input name="DocumentDate" type="date" class="form-control" required></div><div class="col-sm-12 form-group"><label>Dokumen PDF / JPG / PNG (maksimal 15 MB)</label><input type="file" name="DocumentFile" accept="application/pdf,image/jpeg,image/png" required></div></div><button class="btn btn-primary">Upload Surat KSOP</button></form></div></div><div class="box"><div class="box-body table-responsive"><table class="table table-striped"><tr><th>Area</th><th>Nomor / Tanggal</th><th>File</th><th>Aksi</th></tr><?php foreach($documents as $d): ?><tr><td><?= (int)$d['SpbbID'] ?></td><td><?= html_escape($d['ReferenceNo'].' / '.$d['DocumentDate']) ?></td><td><?= html_escape($d['OriginalName']) ?></td><td><a target="_blank" href="<?= site_url('Pipeline_setup/ksop_file/'.$d['KsopID']) ?>">View</a> &middot; <a href="<?= site_url('Pipeline_setup/ksop_file/'.$d['KsopID']).'?download=1' ?>">Download</a> · <a href="<?= site_url('Pipeline_documents/edit/ksop/'.(int)$d['KsopID']) ?>">Edit</a><?php $action_type='ksop';$action_id=(int)$d['KsopID'];$this->load->view('pipeline/document_delete',compact('action_type','action_id')); ?></td></tr><?php endforeach; ?><?php if(!$documents): ?><tr><td colspan="4">Belum ada surat KSOP.</td></tr><?php endif; ?></table></div></div></section></div>